describe('User Language Preference Settings', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!',
    username: 'testuser'
  };

  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
    cy.clearLocalStorage();

    // Login
    cy.get('[data-testid="login-email"]').type(testUser.email);
    cy.get('[data-testid="login-password"]').type(testUser.password);
    cy.get('[data-testid="login-submit"]').click();
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Navigate to profile settings
    cy.get('[data-testid="user-menu-trigger"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();
    cy.get('[data-testid="settings-page-title"]').should('contain', 'Settings');
  });

  it('should successfully change language preference from English to Spanish', () => {
    // Navigate to language settings section
    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').should('be.visible');

    // Verify current language is English
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'English');

    // Change language to Spanish
    cy.get('[data-testid="language-preference-dropdown"]').click();
    cy.get('[data-testid="language-option-es"]').click();

    // Verify selection changed
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'Español');

    // Save settings
    cy.get('[data-testid="save-settings-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Preferencias guardadas');

    // Verify persistence by reloading
    cy.reload();
    cy.get('[data-testid="user-menu-trigger"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();
    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'Español');
  });

  it('should handle language change with unsaved changes warning', () => {
    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').click();
    cy.get('[data-testid="language-option-fr"]').click();

    // Verify language changed in dropdown
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'Français');

    // Attempt to navigate away without saving
    cy.get('[data-testid="settings-general-section"]').click();

    // Verify unsaved changes warning appears
    cy.get('[data-testid="unsaved-changes-modal"]').should('be.visible');
    cy.get('[data-testid="unsaved-changes-modal"]').should('contain', 'You have unsaved changes');

    // Click discard changes
    cy.get('[data-testid="discard-changes-button"]').click();

    // Verify language reverted
    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'English');
  });

  it('should support multiple language options and display correctly', () => {
    const languages = [
      { code: 'en', name: 'English' },
      { code: 'es', name: 'Español' },
      { code: 'fr', name: 'Français' },
      { code: 'de', name: 'Deutsch' },
      { code: 'ja', name: '日本語' }
    ];

    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').click();

    // Verify all language options are available
    languages.forEach((lang) => {
      cy.get(`[data-testid="language-option-${lang.code}"]`)
        .should('be.visible')
        .should('contain', lang.name);
    });
  });

  it('should apply language preference to UI immediately after save', () => {
    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').click();
    cy.get('[data-testid="language-option-de"]').click();
    cy.get('[data-testid="save-settings-button"]').click();

    // Verify success message appears in German
    cy.get('[data-testid="success-toast"]').should('contain', 'Einstellungen gespeichert');

    // Verify UI elements are translated
    cy.get('[data-testid="settings-page-title"]').should('contain', 'Einstellungen');
    cy.get('[data-testid="save-settings-button"]').should('contain', 'Speichern');
  });

  it('should handle language preference change with network error gracefully', () => {
    cy.intercept('POST', '/api/user/preferences', { statusCode: 500, body: { error: 'Server error' } });

    cy.get('[data-testid="settings-language-section"]').click();
    cy.get('[data-testid="language-preference-dropdown"]').click();
    cy.get('[data-testid="language-option-it"]').click();
    cy.get('[data-testid="save-settings-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to save preferences');

    // Verify language preference reverted to previous selection
    cy.get('[data-testid="language-preference-dropdown"]').should('contain', 'English');
  });
});
